"""Final interview feedback / report generated by Gemini."""
from datetime import datetime

from sqlalchemy import Column, DateTime, Float, ForeignKey, Integer, Text, JSON
from sqlalchemy.orm import relationship

from app.database.database import Base


class Feedback(Base):
    __tablename__ = "feedback"

    id = Column(Integer, primary_key=True, index=True)
    interview_id = Column(
        Integer, ForeignKey("interviews.id"), nullable=False, index=True
    )

    summary = Column(Text, nullable=True)
    strengths = Column(JSON, nullable=True)
    weaknesses = Column(JSON, nullable=True)
    technical_improvements = Column(JSON, nullable=True)
    communication_improvements = Column(JSON, nullable=True)
    nonverbal_improvements = Column(JSON, nullable=True)
    recommendations = Column(JSON, nullable=True)
    practice_topics = Column(JSON, nullable=True)

    overall_score = Column(Float, default=0.0)

    created_at = Column(DateTime, default=datetime.utcnow)

    interview = relationship("Interview", back_populates="feedback")
